--		="INSERT INTO [dbo].[TempPPBurdenRates] VALUES('" & A2 & "','" & B2 & "','" & C2 & "','" & D2 & "','" & E2 & "','" & F2 & "','" & G2 & "','" & H2 & "','" & I2 & "','" & J2 & "','" & K2 & "','" & L2 & "','" & M2 & "','" & N2 & "','" & O2 & "','" & P2 & "','" & Q2 & "','" & R2 & "','" & S2 & "','" & T2 & "','" & U2 & "','" & V2 & "','" & W2 & "','" & X2 & "','" & Y2 & "','" & Z2 & "','" & AA2 & "','" &  AB2 & "','" &  AC2 & "','" & AD2 & "','" &  AE2 & "','" &  AF2 & "','" &  AG2 & "','" &  AH2 & "','" &  AI2 & "','" &  AJ2 & "','" &  AK2 & "','" &  AL2 & "','" &  AM2 & "','" &  AN2 & "','" &  AO2 & "','" &  AP2 & "','" &  AQ2 & "','" &  AR2 & "','" &  AS2 & "','" &  AT2 & "','" & AU2 & "','" &  AV2 & "','" & AW2 & "','" &  AX2 & "','" &  AY2 & "','" & AZ2 & "','" & BA2 & "','" & BB2 & "','" & BC2 & "','" & BD2 & "','" & BE2 & "','" & BF2 & "','" & BG2 & "','" & BH2 & "','" & BI2 & "','" & BJ2 & "','" & BK2 & "','" & BL2 & "','" & BM2 & "','" & BN2 & "','" & BO2  & "','" & BP2 & "','" & BQ2 & "','" & BR2 & "','" & BS2 & "','" & BT2 & "','" & BU2 & "','" & BV2 & "','" & BW2 & "','" & BX2 & "','" & BY2 & "','" & BZ2 & "','" & CA2 & "','" & CB2 & "','" & CC2 & "','" & CD2 & "','" & CE2 & "','" & CF2 & "',2);"
