 IF  EXISTS (SELECT 1 FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[ExportProPricerDirectRates]') AND type in (N'P', N'PC'))
	DROP PROCEDURE [dbo].[ExportProPricerDirectRates];

